appendix(19,True)
table(['Dataset or comparison','Observed result','Scope and decision use'],[
 ['BPS and Polri registered vehicles','Seven public annual tables for 2019–2025; 20,907,972 passenger vehicles in the 2025 register.','This describes registrations, not BEV demand, Toyota vehicles, or active Auto2000 customers.'],
 ['Indonesian public charging snapshot','2,454 consolidated station records and 3,767 distinct charger-box IDs.','Useful to identify where access needs checking. Registry entries do not establish uptime, queues or compatibility.'],
 ['Auto2000-name check','15 entries by operator-brand field versus 28 by station name. The other 13 include Toyota or Lexus restriction markers.','Check access and naming before offering a site as a usable fallback.'],
 ['Branch-coordinate sensitivity','27/28 Auto2000-named records have another mapped site within 5 km straight line. Substituting five official direction coordinates changes that to 28/28.','A coordinate discrepancy can change the apparent gap. Straight-line proximity does not imply drive time or an available charger.'],
 ],[5.05,6.0,5.95])
